clean = '''def ref_match(pattern, text):
    """Backtracking reference matcher for the documented pattern grammar."""
    def parse(i):
        alts, seq = [], []
        while i < len(pattern) and pattern[i] != ')':
            if pattern[i] == '|':
                alts.append(seq); seq = []; i += 1
            else:
                atom, i = parse_atom(i)
                seq.append(atom)
        alts.append(seq)
        return alts, i
    def parse_atom(i):
        node, i = parse_primary(i)
        while i < len(pattern) and pattern[i] == '*':
            i += 1
            node = ('*', node)
        return node, i
    def parse_primary(i):
        c = pattern[i]
        if c == '(':
            alts, j = parse(i + 1)
            return ('u', alts), j + 1
        if c == '[':
            items = []
            j = i + 1
            while pattern[j] != ']':
                if pattern[j] == '\\\\':
                    low = pattern[j + 1]; j += 2
                else:
                    low = pattern[j]; j += 1
                if j < len(pattern) and pattern[j] == '-' and pattern[j + 1] != ']':
                    if pattern[j + 1] == '\\\\':
                        high = pattern[j + 2]; j += 3
                    else:
                        high = pattern[j + 1]; j += 2
                    items.append((ord(low), ord(high)))
                else:
                    items.append((ord(low), ord(low)))
            return ('c', items), j + 1
        if c == '\\\\':
            return ('l', pattern[i + 1]), i + 2
        return ('l', c), i + 1
    def match_seq(seq, pos):
        if not seq:
            yield pos
            return
        for after in match_atom(seq[0], pos):
            for done in match_seq(seq[1:], after):
                yield done
    def match_atom(atom, pos):
        kind = atom[0]
        if kind == '*':
            positions = [pos]; seen = {pos}; index = 0
            while index < len(positions):
                here = positions[index]; index += 1
                yield here
                for after in match_atom(atom[1], here):
                    if after not in seen:
                        seen.add(after); positions.append(after)
            return
        if kind == 'l':
            if pos < len(text) and text[pos] == atom[1]:
                yield pos + 1
            return
        if kind == 'c':
            if pos < len(text) and any(low <= ord(text[pos]) <= high
                                       for low, high in atom[1]):
                yield pos + 1
            return
        for alt in atom[1]:
            for done in match_seq(alt, pos):
                yield done
    alts, _ = parse(0)
    return any(p == len(text) for alt in alts for p in match_seq(alt, 0))

